import{_ as t,o,c as a,ah as i}from"./chunks/framework.CgKFW5Fx.js";const n="data:image/png;base64,",s="data:image/png;base64,",r="data:image/png;base64,",A="/projects/Aurora930-Pro/en/latest/assets/image5.X8qAmHtM.png",m="/projects/Aurora930-Pro/en/latest/assets/image6.C8YMC_zi.png",l="/projects/Aurora930-Pro/en/latest/assets/image7.CH9e6dt6.png",d="/projects/Aurora930-Pro/en/latest/assets/image8.CH7rrZp3.png",c="/projects/Aurora930-Pro/en/latest/assets/image9.BeVbzOdS.png",h="/projects/Aurora930-Pro/en/latest/assets/image10.CDJuCh6D.png",g="/projects/Aurora930-Pro/en/latest/assets/image11.DzCIQ-vk.png",p="/projects/Aurora930-Pro/en/latest/assets/image12.BUB1_d23.png",u="/projects/Aurora930-Pro/en/latest/assets/image13.r0E3coku.png",w="/projects/Aurora930-Pro/en/latest/assets/image14.CC2-wxAk.png",b="/projects/Aurora930-Pro/en/latest/assets/image15.BWw9w7mf.png",f="/projects/Aurora930-Pro/en/latest/assets/image16.DZQQ9GNZ.png",j=JSON.parse('{"title":"3. Configuration and Usage in Windows","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Configuration_and_Usage_in_Windows.md","filePath":"docs/3.Configuration_and_Usage_in_Windows.md"}'),U={name:"docs/3.Configuration_and_Usage_in_Windows.md"};function C(z,e,M,q,D,S){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-configuration-and-usage-in-windows" tabindex="-1">3. Configuration and Usage in Windows <a class="header-anchor" href="#_3-configuration-and-usage-in-windows" aria-label="Permalink to &quot;3. Configuration and Usage in Windows&quot;">​</a></h1><h2 id="_3-1-environment-setup" tabindex="-1">3.1 Environment Setup <a class="header-anchor" href="#_3-1-environment-setup" aria-label="Permalink to &quot;3.1 Environment Setup&quot;">​</a></h2><p>(1) First, unzip the software package: <a href="./Appendix.html">deptrum-scope-windows-amd64-v3.6.45.zip</a></p><p>(2) Install the device driver: Navigate to the <code>deptrum-scope/driver</code> folder inside the unzipped package and run <a href="./Appendix.html">WinUsb-InstallDriver.exe</a>. Follow the on-screen instructions to complete the installation.</p><img loading="lazy" height="31" width="271" src="'+n+'" class="common_img"><p>(3) Launch the DeptrumScope application: No installation is required. After connecting the camera module, go to the <code>deptrum-scope</code> folder and double-click <code>DeptrumScope.exe</code> to start the program.</p><img loading="lazy" height="41" width="205" src="'+s+'" class="common_img"><p>(4) If you encounter a missing DLL error when running the GUI, try installing the <a href="./Appendix.html">VC_redist.x64.exe</a> (version 2015 or later), then run the program again.</p><img loading="lazy" height="58" width="220" src="'+r+'" class="common_img"><h2 id="_3-2-using-the-gui-tool" tabindex="-1">3.2 Using the GUI Tool <a class="header-anchor" href="#_3-2-using-the-gui-tool" aria-label="Permalink to &quot;3.2 Using the GUI Tool&quot;">​</a></h2><p>(1) Connect the camera. The software will automatically detect and connect to the device—this may take a few seconds. Once connected, a device control tree will appear on the left side. If the camera model is not displayed in the top-left corner, the device has not been detected.</p><img loading="lazy" height="724" width="1919" src="'+A+'" class="common_img"><p>(2) Device information such as the camera model, RGB/TOF firmware versions, serial number (SN), and SDK version will be displayed in the interface.</p><img loading="lazy" height="555" width="808" src="'+m+'" class="common_img"><h3 id="_3-2-1-2d-mode" tabindex="-1">3.2.1 2D Mode <a class="header-anchor" href="#_3-2-1-2d-mode" aria-label="Permalink to &quot;3.2.1 2D Mode&quot;">​</a></h3><p>(1) Switch to the &quot;2D&quot; tab, then click &quot;Start&quot; under the &quot;Stream &amp; Capture&quot; section to begin viewing the image stream.</p><img loading="lazy" height="609" width="1605" src="'+l+'" class="common_img"><p>(2) The status bar will display the device type and the current frame rate (FPS).</p><img loading="lazy" height="565" width="1173" src="'+d+'" class="common_img"><p>(3) To save an image, click the capture button in the &quot;Stream &amp; Capture&quot; section.</p><img loading="lazy" height="195" width="788" src="'+c+'" class="common_img"><p>(4) Left-click on the depth map to display the depth value of a specific point. Right-click to cancel the selection. (As shown in the image below.)</p><img loading="lazy" height="369" width="680" src="'+h+'" class="common_img"><h3 id="_3-2-2-3d-mode" tabindex="-1">3.2.2 3D Mode <a class="header-anchor" href="#_3-2-2-3d-mode" aria-label="Permalink to &quot;3.2.2 3D Mode&quot;">​</a></h3><p>(1) Switch to the &quot;3D&quot; tab, then click &quot;Start&quot; in the &quot;Stream &amp; Capture&quot; section to view the live point cloud along with the coordinate axes and field of view (FOV).</p><p>If the stream is already running, the point cloud will appear automatically.</p><img loading="lazy" height="873" width="1911" src="'+g+'" class="common_img"><p>(2) Use mouse drag and scroll to adjust the viewing angle and zoom level of the point cloud.</p><img loading="lazy" height="849" width="1008" src="'+p+'" class="common_img"><p>(3) Click &quot;Reset&quot; to return the 3D preview to its default view.</p><img loading="lazy" height="285" width="927" src="'+u+'" class="common_img"><p>(4) Uncheck &quot;Play&quot; to pause the point cloud display.</p><img loading="lazy" height="390" width="939" src="'+w+'" class="common_img"><p>(5) Adjust the &quot;Point Size&quot; value to change the size of the point cloud points in real time.</p><img loading="lazy" height="481" width="917" src="'+b+'" class="common_img"><img loading="lazy" height="479" width="916" src="'+f+'" class="common_img">',36)])])}const Q=t(U,[["render",C]]);export{j as __pageData,Q as default};
